def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()

    # Find diagonal runs of at least two equal, non-background cells.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                for er, ec, sr, sc in (
                    (run[0][0], run[0][1], -dr, -dc),
                    (run[-1][0], run[-1][1], dr, dc),
                ):
                    # An endpoint attached to another part of the pattern
                    # is not an exposed end to extend.
                    attached = False
                    run_set = set(run)
                    for ar in range(er - 1, er + 2):
                        for ac in range(ec - 1, ec + 2):
                            if (0 <= ar < h and 0 <= ac < w and
                                (ar, ac) not in run_set and
                                grid[ar][ac] != bg):
                                attached = True
                    if attached:
                        continue

                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
